ALTER TABLE vehicles ADD COLUMN brand TEXT;
ALTER TABLE vehicles ADD COLUMN year INTEGER CHECK(year IS NULL OR year BETWEEN 1980 AND 2100);
ALTER TABLE vehicles ADD COLUMN color TEXT;
ALTER TABLE vehicles ADD COLUMN unit_code TEXT;
ALTER TABLE vehicles ADD COLUMN vin TEXT;
ALTER TABLE vehicles ADD COLUMN default_driver_id TEXT REFERENCES standard_drivers(id);
ALTER TABLE vehicles ADD COLUMN revision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE vehicles ADD COLUMN last_nonce TEXT NOT NULL DEFAULT '';
UPDATE vehicles SET brand=(SELECT brand FROM standard_vehicle_details WHERE vehicle_id=vehicles.id),year=(SELECT year FROM standard_vehicle_details WHERE vehicle_id=vehicles.id),color=(SELECT color FROM standard_vehicle_details WHERE vehicle_id=vehicles.id),default_driver_id=(SELECT driver_id FROM standard_vehicle_details WHERE vehicle_id=vehicles.id) WHERE EXISTS(SELECT 1 FROM standard_vehicle_details WHERE vehicle_id=vehicles.id);
ALTER TABLE standard_drivers ADD COLUMN employee_id TEXT REFERENCES premium_employees(id);
CREATE TRIGGER standard_vehicle_default_driver_insert BEFORE INSERT ON vehicles WHEN NEW.default_driver_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM standard_drivers WHERE id=NEW.default_driver_id AND operator_id=NEW.operator_id AND status='active') BEGIN SELECT RAISE(ABORT,'driver_scope'); END;
CREATE TRIGGER standard_vehicle_default_driver_update BEFORE UPDATE OF default_driver_id ON vehicles WHEN NEW.default_driver_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM standard_drivers WHERE id=NEW.default_driver_id AND operator_id=NEW.operator_id AND status='active') BEGIN SELECT RAISE(ABORT,'driver_scope'); END;
CREATE TRIGGER standard_driver_employee_insert BEFORE INSERT ON standard_drivers WHEN NEW.employee_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM premium_employees WHERE id=NEW.employee_id AND operator_id=NEW.operator_id) BEGIN SELECT RAISE(ABORT,'driver_scope'); END;
CREATE TRIGGER standard_driver_employee_update BEFORE UPDATE OF employee_id ON standard_drivers WHEN NEW.employee_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM premium_employees WHERE id=NEW.employee_id AND operator_id=NEW.operator_id) BEGIN SELECT RAISE(ABORT,'driver_scope'); END;
CREATE TABLE standard_departure_drivers(departure_id TEXT PRIMARY KEY REFERENCES departures(id),operator_id TEXT NOT NULL REFERENCES operators(id),driver_id TEXT NOT NULL REFERENCES standard_drivers(id),driver_name TEXT NOT NULL,assigned_by TEXT NOT NULL REFERENCES users(id),assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER standard_trip_driver_scope BEFORE INSERT ON standard_departure_drivers WHEN NOT EXISTS(SELECT 1 FROM departures d JOIN route_offers r ON r.id=d.offer_id JOIN standard_drivers dr ON dr.id=NEW.driver_id WHERE d.id=NEW.departure_id AND r.operator_id=NEW.operator_id AND dr.operator_id=NEW.operator_id AND dr.status='active') BEGIN SELECT RAISE(ABORT,'driver_scope'); END;
CREATE TRIGGER standard_trip_driver_conflict BEFORE INSERT ON standard_departure_drivers WHEN EXISTS(SELECT 1 FROM standard_departure_drivers old JOIN standard_vehicle_slots os ON os.departure_id=old.departure_id AND os.active=1 JOIN standard_vehicle_slots ns ON ns.departure_id=NEW.departure_id AND ns.active=1 WHERE old.driver_id=NEW.driver_id AND old.departure_id<>NEW.departure_id AND os.starts_at<ns.ends_at AND os.ends_at>ns.starts_at) BEGIN SELECT RAISE(ABORT,'trip_driver_conflict'); END;
CREATE TRIGGER standard_driver_identity_insert BEFORE INSERT ON standard_drivers WHEN NEW.identity_number<>'' AND EXISTS(SELECT 1 FROM standard_drivers WHERE operator_id=NEW.operator_id AND identity_number=NEW.identity_number AND id<>NEW.id) BEGIN SELECT RAISE(ABORT,'driver_identity_conflict'); END;
CREATE TRIGGER standard_driver_identity_update BEFORE UPDATE OF identity_number ON standard_drivers WHEN NEW.identity_number<>'' AND EXISTS(SELECT 1 FROM standard_drivers WHERE operator_id=NEW.operator_id AND identity_number=NEW.identity_number AND id<>NEW.id) BEGIN SELECT RAISE(ABORT,'driver_identity_conflict'); END;
INSERT OR IGNORE INTO schema_migrations(version) VALUES('0033_driver_vehicle_resources');
